def run(rules, seed, ca):
    import numpy as np
    results = []
    for r in rules:
        try:
            m = ca.evaluate(r, seed, steps=64)
        except TypeError:
            m = ca.evaluate(r, seed)
        d = dict(m)
        d['rule'] = r
        try:
            b, s = r.split('/')
            surv = s[1:]
            d['surv_len'] = len(surv)
            d['has_S2'] = '2' in surv
            d['has_S3'] = '3' in surv
        except Exception:
            pass
        results.append(d)
    return results

def run(rules, seed, ca):
    results = []
    for r in rules:
        try:
            m = dict(ca.evaluate(r, seed))
        except Exception as e:
            m = {'copies': 0, 'alive': 0, 'growth': 0.0, 'stable': False, 'fitness': 0.0, 'error': str(e)}
        m['rule'] = r
        bset = r.split('/')[0][1:]
        m['has_B3_or_B4'] = ('3' in bset) or ('4' in bset)
        m['n_survive'] = len(r.split('/')[1][1:])
        results.append(m)
    return results
